WITH scored AS (SELECT id, session_id, page, duration_sec, NTILE(5) OVER (PARTITION BY event_type ORDER BY duration_sec ASC, id ASC) duration_sec_bucket, NTILE(3) OVER (PARTITION BY page, event_type ORDER BY duration_sec ASC, id ASC) duration_sec_bucket_2 FROM web_events) SELECT id, session_id, duration_sec, duration_sec_bucket, duration_sec_bucket_2 FROM scored ORDER BY duration_sec DESC NULLS FIRST, id DESC;
